onClick:
{{
(async () => {

  const edycja = appsmith.store.edycjaUchwalyId != null;
  const nrUchwaly = String(InputNrUchwaly.text ?? "").trim();

  if (
    !SelectNrNaboru.selectedOptionValue ||
    !SelectRodzaj.selectedOptionValue ||
    !DateZatwierdzenie.selectedDate
  ) {
    showAlert(
      "Uzupełnij wymagane dane uchwały.",
      "warning"
    );
    return;
  }

  try {

    // Dodawanie lub edycja uchwały
    const wynik = edycja
      ? await updateUchwala.run()
      : await addUchwala.run();

    // Sprawdzenie, czy zapis zwrócił rekord
    if (!wynik || (Array.isArray(wynik) && wynik.length === 0)) {
      throw new Error("Nie zapisano żadnego rekordu.");
    }

    // Logowanie zdarzenia
    await Log.write(
      edycja ? "UCHWALY_EDIT" : "UCHWALY_ADD",
      (edycja ? "Zmodyfikowano" : "Dodano") +
        " uchwałę" +
        (nrUchwaly ? " nr " + nrUchwaly : "") +
        " (nabór: " + SelectNrNaboru.selectedOptionLabel + ").",
      appsmith.store.session.user.id,
      appsmith.store.session.user.name,
      appsmith.store.session.token
    );

    // Odświeżenie tabeli
    await getUchwaly.run();

    // Zamknięcie formularza
    closeModal("ModalDodajUchwale");

    // Wyczyszczenie trybu edycji
    await storeValue("edycjaUchwalyId", null);

    showAlert(
      edycja
        ? "Dane uchwały zostały zaktualizowane."
        : "Nowa uchwała została dodana.",
      "success"
    );

  } catch (e) {

    console.error("Błąd zapisu uchwały:", e);

    showAlert(
      "Nie udało się zapisać uchwały: " + e.message,
      "error"
    );

  }

})();
}}
